<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { tr, language } from '../i18n'
import { accountApi as api } from '../accountApi'
import ChangePassword from './ChangePassword.vue'
import {MonitorSmartphone, ShieldCheck, ArrowRight, Trash2} from 'lucide-vue-next'
import TwoFactorStatus from './TwoFactorStatus.vue'
const emit=defineEmits(['changed'])
const account=ref<any>(null),sessions=ref<any[]>([]),password=ref(''),otp=ref(''),setup=ref<any>(null),codes=ref<string[]>([]),busy=ref(false),message=ref(''),error=ref('')
async function load(){[account.value,sessions.value]=await Promise.all([api('/account'),api('/account/sessions')])}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false;otp.value='';password.value=''}}
function start(){action(async()=>{codes.value=[];setup.value=await api('/account/2fa/setup','POST',{current_password:password.value})})}
function confirm(){action(async()=>{const r=await api('/account/2fa/confirm','POST',{code:otp.value});codes.value=r.recovery_codes;setup.value=null;await load();message.value=tr('2FA подключена. Сохраните резервные коды в безопасном месте.','2FA enabled. Store recovery codes somewhere safe.')})}
function disable(){if(!window.confirm(tr('Отключить двухфакторную защиту?','Disable two-factor protection?')))return;action(async()=>{await api('/account/2fa/disable','POST',{current_password:password.value},otp.value);await load()})}
function regenerate(){action(async()=>{const r=await api('/account/2fa/recovery','POST',{current_password:password.value},otp.value);codes.value=r.recovery_codes;await load()})}
function revoke(){if(!window.confirm(tr('Завершить все остальные сеансы? Текущий сеанс останется активным.','End all other sessions? The current session will stay active.')))return;action(async()=>{await api('/account/sessions/revoke-others','POST',{current_password:password.value},otp.value);await load();message.value=tr('Все остальные сеансы завершены.','All other sessions ended.')})}
function download(){const url=URL.createObjectURL(new Blob([tr('KINOSOTA · Резервные коды','KINOSOTA · Recovery codes')+'\n\n'+codes.value.join('\n')+'\n\n'+tr('Храните офлайн. Каждый код используется один раз.','Keep offline. Each code can be used once.')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='kinosota-recovery-codes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function qr(svg:string){return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)))}
function date(s:string){return new Date(s).toLocaleString(language.value==='ru'?'ru-RU':'en-US')}
onMounted(()=>load().catch(e=>error.value=e.message));onBeforeUnmount(()=>{setup.value=null;codes.value=[];password.value='';otp.value=''})
</script>
<template>
 <div class="security-stack">
  <p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p>
  <section class="security-card protection-card" v-if="account"><div class="section-line"><span class="section-symbol" aria-hidden="true"><ShieldCheck :size="28"/></span><div class="section-title"><p class="eyebrow">{{tr('ЗАЩИТА АККАУНТА','ACCOUNT PROTECTION')}}</p><h2>{{tr('Двухфакторная аутентификация','Two-factor authentication')}}</h2></div><span class="status" :class="{enabled:account.two_factor_enabled}">{{account.two_factor_enabled?tr('Включена','Enabled'):tr('Не подключена','Not enabled')}}</span></div>
   <TwoFactorStatus :account="account"/>
   <div class="security-story"><p class="muted">{{tr('Коды генерируются локально по стандарту TOTP. Подойдут Google Authenticator, Aegis, 1Password и другие приложения.','Codes are generated locally using TOTP. Use Google Authenticator, Aegis, 1Password or another authenticator.')}}</p><img class="security-phone" src="/account/security-phone.webp" alt="" width="199" height="254"/></div>
   <label v-if="account.password_login_available">{{tr('Текущий пароль для подтверждения действий','Current password to confirm changes')}}<input v-model="password" type="password" autocomplete="current-password" maxlength="1024" /></label>
   <p class="muted" v-if="account.two_factor_enabled">{{tr('Для каждого нового действия используйте новый код из приложения. Уже использованный код повторно не принимается.','Use a fresh authenticator code for each action. Already used codes cannot be replayed.')}}</p><div v-if="setup" class="wizard"><div class="steps">{{tr('1 · Сканирование → 2 · Подтверждение → 3 · Резервные коды','1 · Scan → 2 · Confirm → 3 · Recovery codes')}}</div><img class="qr" :src="qr(setup.qr_svg)" :alt="tr('QR-код для подключения 2FA','QR code for 2FA setup')" /><p>{{tr('Или введите ключ вручную:','Or enter this key manually:')}}</p><code class="secret">{{setup.secret}}</code><form @submit.prevent="confirm"><label>{{tr('Шестизначный код из приложения','Six-digit authenticator code')}}<input v-model="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required /></label><button :disabled="busy">{{tr('Подтвердить подключение','Confirm setup')}}</button><button type="button" class="secondary" @click="setup=null">{{tr('Отмена','Cancel')}}</button></form></div>
   <button class="enable-factor" v-else-if="!account.two_factor_enabled" @click="start" :disabled="busy"><ShieldCheck :size="22" aria-hidden="true"/>{{tr('Подключить 2FA','Enable 2FA')}}<ArrowRight :size="22" aria-hidden="true"/></button>
   <template v-else><p class="muted">{{tr('Осталось резервных кодов:','Recovery codes remaining:')}} {{account.recovery_codes_remaining}}</p><label>{{tr('Код 2FA или резервный код','2FA or recovery code')}}<input v-model="otp" autocomplete="one-time-code" maxlength="64" spellcheck="false" autocapitalize="off" /></label><div class="button-row"><button class="secondary" @click="regenerate" :disabled="busy">{{tr('Обновить резервные коды','Regenerate recovery codes')}}</button><button v-if="account.role!=='admin'" class="danger" @click="disable" :disabled="busy">{{tr('Отключить 2FA','Disable 2FA')}}</button></div><p v-if="account.role==='admin'" class="muted">{{tr('Для администратора 2FA обязательна. Отключение недоступно.','Admin 2FA is mandatory and cannot be disabled.')}}</p></template>
   <div v-if="codes.length" class="recovery"><h3>{{tr('Сохраните 8 резервных кодов','Save your 8 recovery codes')}}</h3><p>{{tr('Каждый код работает один раз. После закрытия страницы коды больше не показываются.','Each code works once. Codes will not be shown again after you leave this page.')}}</p><div class="code-grid"><code v-for="code in codes" :key="code">{{code}}</code></div><div class="button-row"><button @click="download">{{tr('Скачать коды','Download codes')}}</button><button class="secondary" @click="codes=[]">{{tr('Сохранено — скрыть','Saved — hide codes')}}</button></div></div>
  </section>
  <ChangePassword v-if="account?.password_login_available" @changed="load" />
  <section class="security-card devices-card"><img class="devices-art" src="/account/security-devices.webp" width="262" height="108" alt=""/><div class="device-heading"><span class="section-symbol" aria-hidden="true"><MonitorSmartphone :size="28"/></span><div><p class="eyebrow">{{tr('КОНТРОЛЬ ДОСТУПА','ACCESS CONTROL')}}</p><h2>{{tr('Устройства и сеансы','Devices & sessions')}}</h2></div></div><p class="muted">{{tr('Список наблюдавшихся активных сессий. Название устройства берётся из браузера и может быть неточным. Для завершения других сеансов заполните пароль и код выше.','Observed active sessions. Device names come from the browser and may be inaccurate. Enter your password and code above to end other sessions.')}}</p><p v-if="!sessions.length&&!error" class="muted">{{tr('Активных сеансов не найдено.','No active sessions found.')}}</p><ul class="device-list"><li v-for="(s,i) in sessions" :key="i"><MonitorSmartphone class="device-icon" :size="24" aria-hidden="true"/><div><strong>{{s.current?tr('Текущее устройство','This device'):tr('Другое устройство','Other device')}}</strong><small>{{s.device || tr('Неизвестный браузер','Unknown browser')}}</small><small>{{tr('Последняя активность','Last activity')}} · {{date(s.last_seen_at)}}</small></div><span v-if="s.current" class="status enabled">{{tr('Текущий','Current')}}</span></li></ul><button class="revoke-sessions" @click="revoke" :disabled="busy"><Trash2 :size="21" aria-hidden="true"/>{{tr('Завершить все остальные сеансы','End all other sessions')}}</button></section>
 </div>
</template>
<style scoped>
.security-stack{display:grid;gap:20px}.security-card{background:var(--ui-bg);border:1px solid var(--ui-control);border-radius:var(--ui-radius-panel);padding:28px;min-width:0;color:var(--ui-text)}.section-line{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.eyebrow{font-size:14px;letter-spacing:.13em;color:var(--ui-link);margin:0 0 10px}h2{font-size:22px;margin:0 0 12px;letter-spacing:-.025em}h3{font-size:18px}.muted,small{color:var(--ui-secondary);line-height:1.65}.status{display:inline-block;padding:5px 10px;border-radius:var(--ui-radius-panel);background:var(--ui-raised);color:var(--ui-link);font-size:14px;white-space:nowrap}.status.enabled{background:var(--ui-success-bg);color:var(--ui-success)}label{display:block;margin:16px 0;font-size:14px;color:var(--ui-secondary)}input{display:block;width:100%;box-sizing:border-box;background:var(--ui-bg);color:var(--ui-text);border:1px solid var(--ui-control);border-radius:var(--ui-radius);padding:12px;margin-top:8px;font:inherit}input:focus{outline:2px solid var(--ui-control);outline-offset:2px}button{border:1px solid transparent;border-radius:var(--ui-radius);padding:12px 16px;font:inherit;font-size:14px;font-weight:600;background:var(--ui-primary);color:var(--ui-on-primary);cursor:pointer}button:disabled{opacity:.5;cursor:wait}.secondary{background:var(--ui-surface);color:var(--ui-text);border-color:var(--ui-control)}.danger{background:var(--ui-surface);color:var(--ui-danger)}.button-row{display:flex;gap:10px;flex-wrap:wrap}.notice{padding:14px;border-radius:var(--ui-radius);background:var(--ui-surface);color:var(--ui-success);line-height:1.5}.notice.error{background:var(--ui-raised);color:var(--ui-danger)}.wizard{padding:20px;background:var(--ui-bg);border-radius:var(--ui-radius-panel);margin-top:20px}.steps{font-size:14px;color:var(--ui-link);margin-bottom:20px}.qr{background:white;border-radius:var(--ui-radius);width:220px;max-width:100%;height:auto;padding:10px;box-sizing:border-box}.secret{display:block;overflow-wrap:anywhere;color:var(--ui-link);user-select:all}.recovery{padding:20px;border:1px solid var(--ui-control);border-radius:var(--ui-radius);margin-top:20px}.code-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.code-grid code{font-size:14px;padding:10px;background:var(--ui-bg);color:var(--ui-link);border-radius:var(--ui-radius);overflow-wrap:anywhere}.device-list{list-style:none;padding:0;margin:20px 0}.device-list li{display:flex;gap:14px;padding:18px 0;border-bottom:1px solid var(--ui-control);align-items:flex-start}.device-list li>div{flex:1;min-width:0}.device-list small{display:block;font-size:14px;overflow-wrap:anywhere}.device-icon{font-size:24px;color:var(--ui-link)}@media(max-width:620px){.security-card{padding:20px}.section-line{flex-direction:column}.code-grid{grid-template-columns:1fr}h2{font-size:20px}.device-list .status{display:none}}
.security-stack{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;align-items:start}.security-stack>.security-card:first-of-type{grid-column:1;grid-row:1/span 2}.security-card,.security-stack :deep(.password-security){background:var(--ui-surface);border-color:var(--ui-border);border-radius:var(--ui-radius-panel)}.security-stack>.notice{grid-column:1/-1}.security-stack :deep(.fields){grid-template-columns:1fr;gap:0}.section-line{flex-wrap:wrap}.device-list .status{white-space:normal}@media(max-width:1150px){.security-stack{grid-template-columns:1fr}.security-stack>.security-card:first-of-type{grid-column:auto;grid-row:auto}}
/* Cinematic visual layer only. Account actions and secret handling are unchanged. */
.security-stack{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:22px;align-items:stretch}
.security-stack>.protection-card:first-of-type{grid-column:1;grid-row:1}.security-stack>.devices-card{grid-column:2;grid-row:1}.security-stack :deep(.password-security){grid-column:1/-1;grid-row:2}
.security-card{position:relative;overflow:hidden;border:1px solid #273f59;border-radius:12px;padding:26px;background:radial-gradient(ellipse at top right,#12376850,transparent 70%),linear-gradient(145deg,#0b1829,#08121c);color:#f2f6ff}
.security-card .muted,.security-card small{color:#b7c8dc}.section-line{display:grid;grid-template-columns:54px minmax(0,1fr);gap:16px;margin-bottom:22px}.section-title{min-width:0}.section-line>.status{grid-column:2;justify-self:start;margin-top:-8px;background:#3d2039;color:#ff9ab0;border-radius:24px}.section-line>.status.enabled{background:#0b352e;color:#6ce6c7}
.section-symbol{width:54px;height:54px;display:flex;align-items:center;justify-content:center;border:1px solid #234f9e;border-radius:12px;background:linear-gradient(135deg,#0a3880,#082856);color:#80c8ff;flex-shrink:0}
.eyebrow{color:#59b5ff;font-size:14px;letter-spacing:.08em;line-height:1.5;margin:3px 0 8px}h2{font-size:22px;line-height:1.3;margin:0;letter-spacing:-.025em}.security-story{display:grid;grid-template-columns:minmax(0,1fr) 120px;align-items:center;gap:10px;margin:0 0 22px}.security-story>.muted{margin:0;font-size:16px}.security-phone{width:120px;height:165px;object-fit:contain;justify-self:end;mask-image:linear-gradient(transparent,#000 12%,#000 88%,transparent)}
.enable-factor{display:flex;align-items:center;justify-content:center;gap:14px;min-height:54px;padding:15px 22px;width:100%;border:1px solid #2b9cff;border-radius:8px;background:linear-gradient(105deg,#0873cf,#0865e6);box-shadow:0 5px 20px #007bff30;color:#fff;font-size:17px;font-weight:700}.enable-factor>svg:last-child{margin-left:auto}.enable-factor>svg:first-child{margin-right:auto}.enable-factor:hover:not(:disabled){background:linear-gradient(105deg,#0674c6,#065ce3)}
.device-heading{position:relative;z-index:1;display:flex;gap:16px;align-items:flex-start;margin-bottom:26px}.device-heading>div{min-width:0}.devices-art{position:absolute;top:16px;right:0;width:150px;height:80px;object-fit:contain;opacity:.24;pointer-events:none}.devices-card>.muted{font-size:16px;line-height:1.6}.device-list{margin-top:24px;border-top:1px solid #273e54}.device-list li{flex-wrap:wrap;border-bottom-color:#273e54}.device-list .device-icon{color:#98d2ff;flex-shrink:0}.device-list .status.enabled{background:#0b352e;color:#6ce6c7;border-radius:24px;font-size:14px}.device-list li>div{min-width:130px}.revoke-sessions{display:flex;align-items:center;justify-content:center;gap:14px;min-height:52px;width:100%;border:1px solid #f06883;background:#0c1520;color:#ff8ba3;text-align:left;line-height:1.4}.revoke-sessions svg{flex-shrink:0}.revoke-sessions:hover:not(:disabled){background:#321c2a}
.security-card button:focus-visible{outline:2px solid #9ed8ff;outline-offset:4px}.security-card input:focus{outline-color:#9ed8ff}.security-card .wizard{background:#08121c}.security-stack :deep(.password-security){border-color:#273f59;background:linear-gradient(145deg,#0b1829,#08121c)}
@media(min-width:1500px){.section-line{grid-template-columns:54px minmax(0,1fr) auto}.section-line>.status{grid-column:3;grid-row:1;max-width:100%;margin:0;font-size:14px}.security-story{grid-template-columns:minmax(0,1fr) 150px}.security-phone{width:150px;height:190px}}
@media(max-width:1199px){.security-stack{grid-template-columns:1fr}.security-stack>.protection-card:first-of-type,.security-stack>.devices-card,.security-stack :deep(.password-security){grid-column:auto;grid-row:auto}.security-stack>.protection-card{order:1}.security-stack>.devices-card{order:2}.security-stack :deep(.password-security){order:3}.security-stack>.notice{order:-1}.security-story{grid-template-columns:minmax(0,1fr) 150px}.security-phone{width:150px;height:180px}}
